// Package ogcard paints the 1200×630 Open Graph cards for Sintaxe.
//
// The default masthead lives at web/static/og.png (generated by cmd/genog).
// Article shares hit GET /og/{slug} and reuse this painter so the title is
// in the PNG WhatsApp and LinkedIn actually fetch.
package ogcard

import (
	"fmt"
	"image"
	"image/png"
	"io"
	"net/url"

	"github.com/puppe1990/matheuspuppe-blog/internal/models"
)

const (
	Width  = 1200
	Height = 630
)

// Card is one painted share image. Site=true is the journal masthead; otherwise
// Title is the essay headline.
type Card struct {
	Title  string
	Kicker string
	Byline string
	Host   string
	Site   bool
}

func SiteCard(host string) Card {
	if host == "" {
		host = defaultHost
	}
	return Card{
		Site:   true,
		Title:  "Sintaxe",
		Kicker: "Jornal de Tecnologia",
		Byline: "sistemas, IA e o ofício de construir",
		Host:   host,
	}
}

func ArticleCard(article models.Article, host string) Card {
	if host == "" {
		host = defaultHost
	}
	byline := article.Author.Name
	if article.ReadTimeMinutes > 0 {
		byline = fmt.Sprintf("%s  ·  %d min", article.Author.Name, article.ReadTimeMinutes)
	}
	return Card{
		Title:  article.Title,
		Kicker: article.Category,
		Byline: byline,
		Host:   host,
	}
}

const defaultHost = "sintaxe.apps.gestaobem.com"

// HostOf keeps the share URL as a hostname, never a scheme-prefixed AppURL.
func HostOf(appURL string) string {
	u, err := url.Parse(appURL)
	if err != nil || u.Hostname() == "" {
		return defaultHost
	}
	return u.Hostname()
}

func Render(card Card) (image.Image, error) {
	if err := loadFonts(); err != nil {
		return nil, err
	}
	return paint(card)
}

func WritePNG(w io.Writer, card Card) error {
	img, err := Render(card)
	if err != nil {
		return err
	}
	return png.Encode(w, img)
}
